// Zusammenfassung der Ergebnisse
const stats = $('Deduplicate & Group Keywords').item.json.stats;
const sheetUrl = $('Extract Sheet ID').item.json.spreadsheet_url;
const seedKeyword = $('Extract Task Data').item.json.seed_keyword;

return [{
  json: {
    success: true,
    seed_keyword: seedKeyword,
    total_raw_keywords: stats.total_raw,
    total_unique_keywords: stats.total_unique,
    total_keyword_groups: stats.total_groups,
    google_sheet_url: sheetUrl,
    tasks_created: stats.total_groups,
    message: `Keyword Research abgeschlossen: ${stats.total_groups} Keywords als ClickUp Tasks erstellt. Sheet: ${sheetUrl}`
  }
}];

// AI-Antwort parsen und Seed-Keywords extrahieren
const response = $input.first().json;
const content = response.content?.[0]?.text || '';

// Seeds aus Text extrahieren (eine pro Zeile)
const seeds = content
  .split('\n')
  .map(line => line.trim())
  .filter(line => line.length > 0 && line.length < 60)
  .filter(line => !line.match(/^\d+[.):]/))  // Nummerierung entfernen
  .map(line => line.replace(/^[-•*]\s*/, '').trim())  // Aufzählungszeichen
  .filter(line => line.length > 1);

// Maximal 15 Seeds
const finalSeeds = seeds.slice(0, 15);

// Seed-Keyword aus Extract Task Data als Fallback
const mainSeed = $('Extract Task Data').item.json.seed_keyword;
if (!finalSeeds.includes(mainSeed) && !finalSeeds.some(s => s.toLowerCase() === mainSeed.toLowerCase())) {
  finalSeeds.unshift(mainSeed);
}

// Jedes Seed als eigenes Item
return finalSeeds.map((seed, i) => ({
  json: {
    seed_keyword: seed,
    seed_index: i,
    total_seeds: finalSeeds.length
  }
}));

// Alle Batch-Suggestion-Ergebnisse sammeln
const allItems = $input.all();
const allKeywords = [];

for (const response of allItems) {
  const tasks = response.json.tasks || [];
  for (const task of tasks) {
    if (task.status_code !== 20000) continue;
    const items = task?.result?.[0]?.items || [];
    for (const item of items) {
      const kw = item.keyword_data || item;
      const keyword = (kw.keyword || item.keyword || '').toLowerCase().trim();
      if (!keyword) continue;
      allKeywords.push({
        keyword: keyword,
        search_volume: kw.keyword_info?.search_volume || item.keyword_info?.search_volume || 0,
        cpc: kw.keyword_info?.cpc || item.keyword_info?.cpc || 0,
        competition: kw.keyword_info?.competition || item.keyword_info?.competition || 0,
        search_intent: (kw.search_intent_info?.main_intent || item.search_intent_info?.main_intent || 'informational').toLowerCase(),
        source: 'suggestions'
      });
    }
  }
}

return [{ json: { keywords: allKeywords, count: allKeywords.length } }];

// Related Keywords parsen
const response = $input.first().json;
const allKeywords = [];
const tasks = response.tasks || [];

for (const task of tasks) {
  if (task.status_code !== 20000) continue;
  const items = task?.result?.[0]?.items || [];
  for (const item of items) {
    const kd = item.keyword_data || {};
    const keyword = (kd.keyword || '').toLowerCase().trim();
    if (keyword) {
      allKeywords.push({
        keyword: keyword,
        search_volume: kd.keyword_info?.search_volume || 0,
        cpc: kd.keyword_info?.cpc || 0,
        competition: kd.keyword_info?.competition || 0,
        search_intent: (kd.search_intent_info?.main_intent || 'informational').toLowerCase(),
        source: 'related'
      });
    }
    // Related keywords aus dem Cluster
    const related = item.related_keywords || [];
    for (const rel of related) {
      const rKw = (rel.keyword || '').toLowerCase().trim();
      if (rKw) {
        allKeywords.push({
          keyword: rKw,
          search_volume: rel.keyword_info?.search_volume || 0,
          cpc: rel.keyword_info?.cpc || 0,
          competition: rel.keyword_info?.competition || 0,
          search_intent: (rel.search_intent_info?.main_intent || 'informational').toLowerCase(),
          source: 'related_cluster'
        });
      }
    }
  }
}

return [{ json: { keywords: allKeywords, count: allKeywords.length } }];

// Alle Keywords zusammenführen + Relevanzfilter
const allInputs = $input.all();
const allKeywords = [];

for (const input of allInputs) {
  const kws = input.json.keywords || [];
  allKeywords.push(...kws);
}

// Leere Keywords entfernen
const filtered = allKeywords.filter(kw => kw.keyword && kw.keyword.length > 0);

// RELEVANZFILTER: Nur Keywords die thematisch zum Hauptthema passen
// Kernwörter aus dem Task-Namen extrahieren
const taskName = $('Extract Task Data').item.json.original_task_name.toLowerCase();
