  'der', 'die', 'das', 'den', 'dem', 'des', 'ein', 'eine',
  'und', 'oder', 'für', 'mit', 'von', 'in', 'im', 'auf', 'aus',
  'zu', 'bei', 'nach', 'über', 'unter', 'vor', 'an', 'am'
]);

const coreWords = new Set();
// Aus Task-Name
taskName.replace(/[-–—]/g, ' ').split(/\s+/).forEach(w => {
  if (w.length > 2 && !STOP_WORDS.has(w)) coreWords.add(w);
});
// Aus allen Seeds
seeds.forEach(seed => {
  seed.replace(/[-–—]/g, ' ').split(/\s+/).forEach(w => {
    if (w.length > 2 && !STOP_WORDS.has(w)) coreWords.add(w);
  });
});

// Keyword ist relevant wenn es mindestens 1 Kernwort enthält
const relevant = filtered.filter(kw => {
  const kwLower = kw.keyword.toLowerCase().replace(/[-–—]/g, ' ');
  return [...coreWords].some(core => kwLower.includes(core));
});

return [{ json: {
  all_keywords: relevant,
  total_raw: filtered.length,
  total_relevant: relevant.length,
  core_words: [...coreWords],
  filtered_out: filtered.length - relevant.length
} }];

