    return [];
  }

  return [{ json: { task_id: body.task_id, source: 'clickup_webhook' } }];
}

// Format 2: Manueller Webhook-Call mit task_id
if (body.task_id) {
  return [{ json: { task_id: body.task_id, source: 'manual' } }];
}

// Kein gültiges Format → stoppen
return [];

