  'durch', 'gegen', 'zwischen', 'neben', 'seit', 'während',
  'ist', 'sind', 'wird', 'werden', 'hat', 'haben',
  'als', 'wie', 'was', 'wer', 'wo', 'wann', 'warum',
  'ich', 'du', 'er', 'sie', 'es', 'wir', 'ihr',
  'sich', 'man', 'auch', 'noch', 'schon', 'so', 'sehr',
  'nur', 'nicht', 'kein', 'keine', 'keinen', 'keiner',
  'zu', 'ab', 'ob', 'wenn', 'weil', 'dass', 'damit'
]);

// Normalisierung: Bindestriche→Leerzeichen, Stoppwörter raus, sortieren
function normalizeForGrouping(keyword) {
  const words = keyword
    .toLowerCase()
    .replace(/[-–—]/g, ' ')           // Bindestriche → Leerzeichen
    .replace(/[^a-zäöüß0-9\s]/g, '')  // Sonderzeichen weg
    .split(/\s+/)
    .filter(w => w.length > 1 && !STOP_WORDS.has(w));

  // Einfaches Stemming
  const stemmed = words.map(w => {
    if (w.length > 5) {
      if (w.endsWith('ungen')) return w.slice(0, -5);
      if (w.endsWith('ung')) return w.slice(0, -3);
      if (w.endsWith('heit')) return w.slice(0, -4);
      if (w.endsWith('keit')) return w.slice(0, -4);
      if (w.endsWith('isch')) return w.slice(0, -4);
      if (w.endsWith('lich')) return w.slice(0, -4);
      if (w.endsWith('ieren')) return w.slice(0, -5);
      if (w.endsWith('en')) return w.slice(0, -2);
      if (w.endsWith('er')) return w.slice(0, -2);
      if (w.endsWith('es')) return w.slice(0, -2);
      if (w.endsWith('em')) return w.slice(0, -2);
      if (w.endsWith('te')) return w.slice(0, -2);
      if (w.endsWith('st')) return w.slice(0, -2);
      if (w.endsWith('e')) return w.slice(0, -1);
      if (w.endsWith('s')) return w.slice(0, -1);
    }
    return w;
  }).filter(w => w.length > 1);

  return stemmed.sort().join(' ');
}

// Prüfe ob zwei Keys zusammengehören (70%+ Wort-Overlap)
function shouldMerge(key1, key2) {
  if (key1 === key2) return true;
  const words1 = new Set(key1.split(' '));
  const words2 = new Set(key2.split(' '));
  const intersection = [...words1].filter(w => words2.has(w));
  const maxLen = Math.max(words1.size, words2.size);
  if (maxLen === 0) return false;
  return intersection.length / maxLen >= 0.7;
}

// Phase 1: Exakte Duplikate
const deduped = new Map();
for (const kw of allKeywords) {
  // Auch Bindestriche bei Dedup normalisieren
  const key = kw.keyword.toLowerCase().replace(/[-–—]/g, ' ').trim().replace(/\s+/g, ' ');
  const existing = deduped.get(key);
  if (!existing || kw.search_volume > existing.search_volume) {
    deduped.set(key, kw);
  }
}

const completeList = Array.from(deduped.values())
  .sort((a, b) => b.search_volume - a.search_volume);

// Phase 2: Normalisierte Gruppen
const normalizedMap = new Map();
for (const kw of completeList) {
  const normalized = normalizeForGrouping(kw.keyword);
  if (!normalizedMap.has(normalized)) {
    normalizedMap.set(normalized, []);
  }
  normalizedMap.get(normalized).push(kw);
}

// Phase 3: Fuzzy-Merge
const groupKeys = Array.from(normalizedMap.keys());
const merged = new Map();
const keyMapping = new Map();

for (const key of groupKeys) {
  if (keyMapping.has(key)) continue;
  let bestMatch = null;
  for (const [existingKey] of merged) {
    if (shouldMerge(key, existingKey)) {
      bestMatch = existingKey;
      break;
    }
  }
  if (bestMatch) {
    merged.get(bestMatch).push(...normalizedMap.get(key));
    keyMapping.set(key, bestMatch);
  } else {
    merged.set(key, [...normalizedMap.get(key)]);
    keyMapping.set(key, key);
  }
}

// Phase 4: Pro Gruppe bestes Keyword
const cleanedList = [];
const groupMapping = [];
let groupId = 1;

for (const [normalizedKey, keywords] of merged) {
  keywords.sort((a, b) => b.search_volume - a.search_volume);
  const primary = keywords[0];
  const totalSV = keywords.reduce((sum, kw) => sum + (kw.search_volume || 0), 0);

  cleanedList.push({
    keyword: primary.keyword,
    search_volume: primary.search_volume,
    total_group_volume: totalSV,
    search_intent: primary.search_intent,
    cpc: primary.cpc,
    competition: primary.competition,
    status: 'offen',
    group_id: groupId,
    variations_count: keywords.length,
    variations: keywords.slice(0, 10).map(k => k.keyword).join(', ')
  });

  for (const kw of keywords) {
    groupMapping.push({
      group_id: groupId,
      primary_keyword: primary.keyword,
      keyword: kw.keyword,
      search_volume: kw.search_volume,
      search_intent: kw.search_intent,
      is_primary: kw.keyword === primary.keyword
    });
  }
  groupId++;
}

cleanedList.sort((a, b) => b.search_volume - a.search_volume);

return [{
  json: {
    cleaned_keywords: cleanedList,
    complete_keywords: completeList,
    keyword_groups: groupMapping,
    stats: {
      total_raw: allKeywords.length,
      total_unique: completeList.length,
      total_groups: cleanedList.length,
      reduction_pct: completeList.length > 0
        ? Math.round((1 - cleanedList.length / completeList.length) * 100) + '%'
        : '0%'
    }
  }
}];

// Sheet ID extrahieren und Worksheet-Namen vorbereiten
const sheetResponse = $input.all()[0].json;
const spreadsheetId = sheetResponse.id;
const spreadsheetUrl = `https://docs.google.com/spreadsheets/d/${spreadsheetId}`;

return [{
  json: {
    spreadsheet_id: spreadsheetId,
    spreadsheet_url: spreadsheetUrl
  }
}];

// Daten für alle 3 Worksheets als Sheets API values vorbereiten
const data = $('Deduplicate & Group Keywords').item.json;
const spreadsheetId = $('Extract Sheet ID').item.json.spreadsheet_id;

// Worksheet 1: Bereinigte Keywordliste (1 Keyword pro Gruppe)
const sheet1Header = ['Keyword', 'Suchvolumen', 'Search Intent', 'CPC', 'Competition', 'Status', 'Keyword-Gruppe', 'Variationen'];
const sheet1Rows = data.cleaned_keywords.map(kw => [
  kw.keyword,
  kw.search_volume,
  kw.search_intent,
  kw.cpc,
  kw.competition,
  kw.status,
  kw.group_id,
  kw.variations_count
]);

// Worksheet 2: Komplette Keywordliste (alle Keywords inkl. Variationen)
const sheet2Header = ['Keyword', 'Suchvolumen', 'Search Intent', 'CPC', 'Competition'];
const sheet2Rows = data.complete_keywords.map(kw => [
  kw.keyword,
